#!/usr/bin/env python3
"""Identity realm conformance (doc 06; Phase 0 §10.3; Phase 3 doc 03): checks a Keycloak realm against the rules.

Usage: check-realm-security.py REALM.json [--profile dev|citizens|staff] [--live] [--require-approved-keys] [--self-test]
REALM.json is a realm file from Git or a live partial export (infra/keycloak/apply-realm-policy.py); the live
export also lists Keycloak's built-in clients, flows and default roles, so it is the stronger check.
--live adds the rules only a running realm can meet (pairwise salts generated by Keycloak).
--require-approved-keys (staging, pilot, tests): the staff realm must list approved security-key models (AAGUIDs).
--self-test also feeds weakened copies of the realm and requires each to be rejected (negative controls).
Exit 1 on any violation.

The login flow is evaluated, not pattern-matched: "can the browser flow be completed by someone holding only these
credentials, against an account that has these credentials?" Keycloak semantics: REQUIRED steps must all pass (then
ALTERNATIVE steps are ignored), else one ALTERNATIVE must pass; a CONDITIONAL sub-flow runs only when its conditions
hold (user configured, sub-flow executed). A REQUIRED second factor that the account does not have counts as
PASSED when Keycloak would enrol it at login (its required action is enabled): whoever is at the login page enrols
their own (an ALTERNATIVE step for a missing factor is simply unavailable).
That is the first-enrolment weakness, so it is checked for every account state. Unknown authenticators or conditions
are violations until the checker models them.
Brokered sign-in (staff, institution SSO): the identity-provider redirector reaches only an account that the identity
provider itself created, unless the provider's first-login flow links accounts; then the provider's post-login flow
decides. A security key enrolled at the first SSO sign-in is by design (the institution's identity provider
authenticated the person); every later SSO sign-in needs that key.
"""
import copy
import json
import os
import re
import sys

BUILT_IN_CLIENTS = {"account", "account-console", "admin-cli", "broker", "realm-management", "security-admin-console"}
UUID_PATTERN = "^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"
# What each authenticator needs from the person logging in. None: passes for anyone (identification only).
NEEDS = {
    "auth-cookie": "session",
    "auth-username-form": None,
    "auth-username-password-form": "password",
    "auth-password-form": "password",
    "auth-otp-form": "otp",
    "webauthn-authenticator": "security-key",
    "webauthn-authenticator-passwordless": "passkey",
    "deny-access-authenticator": "impossible",
    "identity-provider-redirector": "external-idp",
    "auth-spnego": "kerberos",
    "auth-x509-client-username-form": "client-certificate",
    "direct-grant-validate-username": None,
    "direct-grant-validate-password": "password",
    "direct-grant-validate-otp": "otp",
    "idp-create-user-if-unique": None,
    "idp-review-profile": None,
    "idp-add-organization-member": None,
}
# First-login steps that attach a brokered identity to an ACCOUNT THAT ALREADY EXISTS (takeover risk across tenants).
LINKING = {"idp-auto-link", "idp-confirm-link", "idp-username-password-form", "idp-email-verification", "idp-detect-existing-broker-user",
           "idp-confirm-override-link"}
ALLOWED_DEFAULT_ROLES = {
    "citizens": {"realm": {"citizen"}, "account": {"view-profile", "manage-account"}},
    "staff": {"realm": set(), "account": {"view-profile"}},
    "dev": {"realm": set(), "account": {"view-profile", "manage-account"}},
}


UNKNOWN = set()
# Missing factor -> the required action Keycloak would use to enrol it at login.
ENROL_ACTION = {"otp": "CONFIGURE_TOTP", "security-key": "webauthn-register", "passkey": "webauthn-register-passwordless"}
EXTERNAL = {"session", "external-idp", "kerberos", "client-certificate"}
IDENTIFIES = {"auth-username-form", "auth-username-password-form", "webauthn-authenticator-passwordless", "auth-cookie",
              "direct-grant-validate-username", "identity-provider-redirector"}


def flows_of(r):
    return {f["alias"]: f for f in r.get("authenticationFlows", [])}


def _active(flow):
    return sorted([e for e in flow.get("authenticationExecutions", []) if e.get("requirement") != "DISABLED"],
                  key=lambda e: e.get("priority", 0))


def _is_condition(e):
    return not e.get("authenticatorFlow") and str(e.get("authenticator", "")).startswith("conditional-")


def can_complete(r, alias, held, account=None):
    """True if someone holding only `held` can complete flow `alias` for an account that has `account` credentials
    (default: what is held, plus a password)."""
    account = (set(held) | {"password"}) if account is None else set(account)
    actions = {a.get("providerId") or a.get("alias") for a in r.get("requiredActions", []) if a.get("enabled", True)} \
        if r.get("requiredActions") else set(ENROL_ACTION.values())  # not listed: Keycloak's defaults are enabled
    ctx = {"flows": flows_of(r), "cfgs": {c["alias"]: c.get("config", {}) for c in r.get("authenticatorConfig", [])}, "actions": actions,
           "idps": [i for i in r.get("identityProviders", []) if i.get("enabled", True)], "realm": r}
    return _run(alias, {"held": set(held), "account": account, "executed": set(), "identified": False}, ctx, 0)


def _authenticator(e, st, ctx, where):
    auth = e.get("authenticator")
    if auth not in NEEDS:
        UNKNOWN.add(f"{where}/{auth}")
        return True
    need = NEEDS[auth]
    if auth == "identity-provider-redirector":
        ok = "external-idp" in st["held"] and any(_brokered(i, st, ctx) for i in ctx["idps"])
        if ok:
            st["identified"] = True
        return ok
    if need is None:
        ok = True
    elif need == "impossible":
        ok = False
    elif need in EXTERNAL:
        ok = need in st["held"]
    elif need in st["account"]:
        ok = need in st["held"]
    elif need == "password" or (need == "passkey" and not st["identified"]) or e.get("requirement") != "REQUIRED":
        ok = False  # nothing of this account to present (an ALTERNATIVE step for a missing factor is just unavailable)
    else:
        ok = ENROL_ACTION.get(need) in ctx["actions"]  # REQUIRED and missing: enrolled at login by whoever is there
    if ok and auth in IDENTIFIES:
        st["identified"] = True
    return ok


def first_broker_flow(r, idp):
    return idp.get("firstBrokerLoginFlowAlias") or r.get("firstBrokerLoginFlow") or "first broker login"


def links_accounts(r, alias):
    """True if a first-login flow can attach the brokered identity to an existing account (the built-in one does)."""
    if alias not in flows_of(r):
        return True  # not in the export: Keycloak's built-in first broker login, which links by e-mail
    return any(contains_authenticator(r, alias, a) for a in LINKING)


def _brokered(idp, st, ctx):
    r = ctx["realm"]
    if "password" in st["account"] and not links_accounts(r, first_broker_flow(r, idp)):
        return False  # a local account is never reached through the identity provider
    post = idp.get("postBrokerLoginFlowAlias")
    if not post:
        return True
    sub = {"held": st["held"], "account": st["account"], "executed": set(), "identified": True}
    return _run(post, sub, ctx, 1)


def _conditions_hold(flow_alias, st, ctx):
    sub = ctx["flows"].get(flow_alias, {})
    execs = _active(sub)
    result = True
    for c in [e for e in execs if _is_condition(e)]:
        kind = c.get("authenticator")
        if kind == "conditional-user-configured":
            needs = [NEEDS.get(x.get("authenticator")) for x in execs if not x.get("authenticatorFlow") and not _is_condition(x)]
            ok = all(n is None or n in st["account"] for n in needs)
        elif kind == "conditional-sub-flow-executed":
            cfg = ctx["cfgs"].get(c.get("authenticatorConfig"), {})
            ran = cfg.get("flow_to_check") in st["executed"]
            ok = ran if cfg.get("check_result", "executed") == "executed" else not ran
        else:
            UNKNOWN.add(f"{flow_alias}/{kind}")
            ok = True
        result = result and ok
    return result


def _run(alias, st, ctx, depth):
    flow = ctx["flows"].get(alias)
    if flow is None or depth > 10:
        return False
    body = [e for e in _active(flow) if not _is_condition(e)]

    def step(e, state):
        if e.get("authenticatorFlow"):
            ok = _run(e.get("flowAlias"), state, ctx, depth + 1)
            if ok:
                state["executed"].add(e.get("flowAlias"))
            return ok
        return _authenticator(e, state, ctx, alias)

    required = [e for e in body if e.get("requirement") in ("REQUIRED", "CONDITIONAL")]
    if required:
        for e in required:
            if e.get("requirement") == "CONDITIONAL" and e.get("authenticatorFlow") and not _conditions_hold(e.get("flowAlias"), st, ctx):
                continue  # conditions false: the sub-flow is skipped
            if not step(e, st):
                return False
        return True
    alternatives = [e for e in body if e.get("requirement") == "ALTERNATIVE"]
    for e in alternatives:
        trial = {"held": st["held"], "account": st["account"], "executed": set(st["executed"]), "identified": st["identified"]}
        if step(e, trial):
            st.update(trial)
            return True
    return not alternatives  # nothing to do at all: passes


def contains_authenticator(r, alias, authenticator, depth=0):
    flow = flows_of(r).get(alias)
    if flow is None or depth > 10:
        return False
    return any((e.get("authenticatorFlow") and contains_authenticator(r, e.get("flowAlias"), authenticator, depth + 1))
               or e.get("authenticator") == authenticator for e in _active(flow))


# Account states checked per profile: a password alone must never complete the login, whatever the account holds
# (including an account that has no second factor yet).
STATES = {
    "citizens": [{"password"}, {"password", "otp"}, {"password", "passkey"}, {"password", "otp", "passkey"}, {"passkey"}, set()],
    "staff": [{"password"}, {"password", "security-key"}, {"password", "otp"}, {"password", "otp", "passkey"},
              {"security-key"}],  # last: an account created by institution SSO, key enrolled
}
SERVICE_ROLES = {"realm-management": {"manage-users", "view-users", "query-users", "view-events"}}


def user_profile(r):
    for comp in r.get("components", {}).get("org.keycloak.userprofile.UserProfileProvider", []):
        raw = comp.get("config", {}).get("kc.user.profile.config")
        if raw:
            return json.loads(raw[0])
    return None


def mappers(c):
    return [m.get("protocolMapper") for m in c.get("protocolMappers", [])]


def claim_mapped(c, claim):
    return any(m.get("config", {}).get("claim.name") == claim for m in c.get("protocolMappers", []))


def audience_core(c):
    return any(m.get("protocolMapper") == "oidc-audience-mapper" and m.get("config", {}).get("included.client.audience") == "civora-core"
               for m in c.get("protocolMappers", []))


def violations(r, profile="dev", live=False, require_approved_keys=False):
    UNKNOWN.clear()
    v = _violations(r, profile, require_approved_keys)
    if live:
        for c in r.get("clients", []):
            for m in c.get("protocolMappers", []):
                if m.get("protocolMapper") == "oidc-sha256-pairwise-sub-mapper" and not m.get("config", {}).get("pairwiseSubAlgorithmSalt"):
                    v.append(f"{c.get('clientId')}: pairwise subject without a salt (run apply-realm-policy.py)")
            if c.get("clientId") == "civora-web" and profile == "citizens" and not c.get("attributes", {}).get("jwks.string"):
                v.append("civora-web: no public key for its client assertions (run apply-realm-policy.py --web-client-jwks)")
    v += [f"flow step {x}: unknown authenticator, add it to the checker before use" for x in sorted(UNKNOWN)]
    return v


CONTEXT_WORDS = [w.strip() for w in open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "keycloak", "password-deny-list",
                                                     "context-words.txt"), encoding="utf-8") if w.strip()]


def _violations(r, profile, require_approved_keys=False):
    v = []
    if r.get("sslRequired") not in ("external", "all"):
        v.append("sslRequired must be 'external' or 'all'")
    if not r.get("bruteForceProtected"):
        v.append("brute-force protection must be on")
    if int(r.get("failureFactor", 30)) > 5:
        v.append("lockout after at most 5 failures")
    if profile in ("citizens", "staff"):
        # Sign-in events feed the person's security notices (ASVS V6.3.5, V6.3.7; Phase 3 doc 15 §7): stored briefly.
        types = set(r.get("enabledEventTypes") or [])
        if not r.get("eventsEnabled") or not {"LOGIN", "LOGIN_ERROR", "UPDATE_CREDENTIAL", "REMOVE_CREDENTIAL"} <= types:
            v.append("sign-in events stored (LOGIN, LOGIN_ERROR, UPDATE_CREDENTIAL, REMOVE_CREDENTIAL) for the security notices")
        if not 600 <= int(r.get("eventsExpiration") or 0) <= 86400:
            v.append("sign-in events kept between 10 minutes and one day (they hold addresses)")
    pol = r.get("passwordPolicy", "")
    m = re.search(r"length\((\d+)\)", pol)
    if not m or int(m.group(1)) < 12:
        v.append("password policy: length >= 12")
    for rule in ("notUsername", "passwordHistory"):
        if rule not in pol:
            v.append(f"password policy: {rule}")
    if profile in ("citizens", "staff"):
        # ASVS 5.0 V6.2.4/V6.2.12 (common and breached passwords) and V6.1.2/V6.2.11 (context-specific words):
        # infra/keycloak/password-deny-list, mounted where Keycloak runs (an import without the file fails).
        if "passwordBlacklist(civora-deny.txt)" not in pol:
            v.append("password policy: passwordBlacklist(civora-deny.txt) (common and breached passwords)")
        rx = re.search(r"regexPattern\((.*)\)\s*(?:and|$)", pol)
        missing = [w for w in CONTEXT_WORDS if not rx or w not in rx.group(1)]
        if not rx or not rx.group(1).startswith("(?is)^(?!.*(?:") or missing:
            v.append(f"password policy: context words refused (regexPattern with a negative look-ahead; missing {missing})")
    if int(r.get("accessTokenLifespan", 300)) > 300:
        v.append("access tokens live at most 5 min")
    if not r.get("revokeRefreshToken") or int(r.get("refreshTokenMaxReuse", 0)) != 0:
        v.append("refresh tokens must be rotated (revokeRefreshToken=true, refreshTokenMaxReuse=0)")
    for c in r.get("clients", []):
        cid = c.get("clientId")
        if c.get("implicitFlowEnabled"):
            v.append(f"{cid}: implicit flow forbidden")
        if c.get("directAccessGrantsEnabled", True) and not c.get("bearerOnly"):
            v.append(f"{cid}: password grant (direct access) forbidden")
        if c.get("publicClient") and c.get("standardFlowEnabled", True):
            if c.get("attributes", {}).get("pkce.code.challenge.method") != "S256":
                v.append(f"{cid}: public client needs PKCE S256")
        for u in c.get("redirectUris", []):
            if u.strip() in ("*", "/*") or re.match(r"^https?://\*", u):
                v.append(f"{cid}: wildcard redirect URI {u}")
    for f in r.get("authenticationFlows", []):
        if len(f.get("description") or "") > 255:
            v.append(f"flow {f.get('alias')}: description longer than 255 characters (Keycloak refuses the import)")
    for u in r.get("users", []):
        for cred in u.get("credentials", []):
            if cred.get("type") == "password" and ("value" in cred or "secretData" in cred):
                v.append(f"user {u.get('username')}: password stored in the realm file")
    # No password grant anywhere: the realm's direct-grant flow must refuse (the built-in admin-cli client allows
    # the password grant in every realm, which would skip the browser flow's second factor).
    flows = flows_of(r)
    if r.get("directGrantFlow") not in flows or any(can_complete(r, r.get("directGrantFlow"), h, a) for h, a in
                                                        (({"password"}, {"password"}), ({"password"}, {"password", "otp"}),
                                                         ({"password", "otp", "security-key", "passkey"}, {"password", "otp", "security-key", "passkey"}))):
        v.append("direct-grant flow must deny every request (deny-access-authenticator)")
    # Default roles: never offline tokens; only what the profile allows.
    allowed = ALLOWED_DEFAULT_ROLES[profile]
    default_name = (r.get("defaultRole") or {}).get("name", f"default-roles-{r.get('realm')}")
    for role in r.get("roles", {}).get("realm", []):
        if role.get("name") == default_name:
            comp = role.get("composites") or {}
            extra = set(comp.get("realm", [])) - allowed["realm"]
            for client, names in (comp.get("client") or {}).items():
                extra |= {f"{client}/{n}" for n in set(names) - allowed.get(client, set())}
            if extra:
                v.append(f"default role grants more than the {profile} profile allows: {', '.join(sorted(extra))}")

    if profile in ("citizens", "staff"):
        if (r.get("attributes") or {}).get("civora.profile") != profile:
            v.append(f"realm attribute civora.profile must be '{profile}'")
        up = user_profile(r)
        if up is None:
            v.append("declarative user profile missing")
        elif up.get("unmanagedAttributePolicy") in ("ENABLED", "ADMIN_EDIT"):
            v.append("unmanaged user attributes must be off (a user could set claims such as tenant_id)")
        if up is not None:
            # Contact details change only through the core, after the new address or number is verified (doc phase-3/16).
            attrs = {a.get("name"): a for a in up.get("attributes", [])}
            for name in ("username", "email"):
                if "user" in ((attrs.get(name) or {}).get("permissions") or {}).get("edit", []):
                    v.append(f"{name} must not be editable by the user on Keycloak's pages (the core changes it once the new address is verified; ASVS V6.3.7)")
            for name in ("phone_number", "phone_number_verified"):
                a = attrs.get(name)
                if a is None:
                    v.append(f"user profile must declare {name}")
                elif (a.get("permissions") or {}).get("edit") != ["admin"] or "user" in (a.get("permissions") or {}).get("view", []):
                    v.append(f"{name} must be visible and editable by administrators only (the core verifies the number)")
        if r.get("editUsernameAllowed"):
            v.append("editUsernameAllowed must be off (the username is the verified address)")
        if any(a.get("providerId") == "UPDATE_EMAIL" and a.get("enabled") for a in r.get("requiredActions", [])):
            v.append("required action UPDATE_EMAIL must be off (e-mail changes go through the core's verified flow)")
        browser = r.get("browserFlow")
        for state in STATES[profile]:
            if can_complete(r, browser, {"password"}, state):
                what = "+".join(sorted(state)) or "no credentials"
                v.append(f"browser flow: a password alone completes the login of an account holding {what}"
                         + (" (a missing second factor is enrolled at login by whoever is there)" if state <= {"password"} else ""))
        if contains_authenticator(r, browser, "auth-username-form"):
            v.append("browser flow asks for the username alone first: the answer reveals whether an account exists")
        for c in r.get("clients", []):
            cid = c.get("clientId")
            if c.get("bearerOnly") or cid in BUILT_IN_CLIENTS:
                continue
            kind = c.get("attributes", {}).get("civora.client-kind")
            if kind not in ("first-party", "relying-party", "service"):
                v.append(f"{cid}: attribute civora.client-kind must be first-party, relying-party or service")
            if kind == "first-party" and not audience_core(c):
                v.append(f"{cid}: first-party client needs the civora-core audience")
            if cid == "civora-web" and profile == "citizens":
                # The web app (a backend-for-frontend) at ASVS 5.0 L3 (Phase 3 doc 14): confidential client with
                # private_key_jwt, pushed authorization requests only, DPoP-bound access tokens (V10.3.5, V10.4.12-16).
                a = c.get("attributes", {})
                if c.get("publicClient") or c.get("clientAuthenticatorType") != "client-jwt":
                    v.append("civora-web: must be a confidential client authenticating with a signed JWT (private_key_jwt)")
                if a.get("token.endpoint.auth.signing.alg") not in ("ES256", "PS256", "EdDSA"):
                    v.append("civora-web: client assertions signed with ES256, PS256 or EdDSA")
                if a.get("use.jwks.url") == "true":
                    v.append("civora-web: the client's public key is pinned in the client (jwks.string), not fetched from a URL")
                if a.get("require.pushed.authorization.requests") != "true":
                    v.append("civora-web: pushed authorization requests (PAR) required")
                if a.get("dpop.bound.access.tokens") != "true":
                    v.append("civora-web: access tokens bound to the client's key (DPoP)")
            if cid == "civora-mobile" and profile == "citizens":
                # The mobile app is a public (native) client: PAR and DPoP-bound tokens are required as for the web app;
                # it cannot keep a client secret, so no client authentication (ASVS V10.4.16 deviation, Phase 3 doc 14).
                a = c.get("attributes", {})
                if a.get("require.pushed.authorization.requests") != "true":
                    v.append("civora-mobile: pushed authorization requests (PAR) required")
                if a.get("dpop.bound.access.tokens") != "true":
                    v.append("civora-mobile: access tokens bound to the app's key (DPoP)")
            if kind == "service" and (c.get("publicClient") or not c.get("serviceAccountsEnabled") or c.get("standardFlowEnabled", True)
                                      or c.get("implicitFlowEnabled") or c.get("directAccessGrantsEnabled", True)):
                v.append(f"{cid}: service client must be confidential, service account only (no browser or password flows)")
        for u in r.get("users", []):
            if u.get("serviceAccountClientId"):
                extra = {f"{k}/{n}" for k, names in (u.get("clientRoles") or {}).items() for n in names if n not in SERVICE_ROLES.get(k, set())}
                extra |= {f"realm/{n}" for n in u.get("realmRoles") or [] if not n.startswith("default-roles-")}
                if extra:
                    v.append(f"service account of {u['serviceAccountClientId']} has roles beyond user management: {', '.join(sorted(extra))}")

    if profile == "dev" and r.get("registrationAllowed"):
        v.append("self-registration must be off")

    if profile == "citizens":
        if r.get("registrationAllowed"):
            v.append("Keycloak self-registration must be off: its page says whether an address exists (registration goes through the core)")
        if not r.get("verifyEmail"):
            v.append("e-mail verification must be on")
        if not can_complete(r, r.get("browserFlow"), {"passkey"}, {"passkey"}):
            v.append("browser flow must accept a passkey (P3-F1)")
        if not can_complete(r, r.get("browserFlow"), {"password", "otp"}, {"password", "otp"}):
            v.append("browser flow must offer password + TOTP as the alternative to passkeys (P3-F1)")
        if r.get("webAuthnPolicyPasswordlessUserVerificationRequirement") != "required":
            v.append("passkeys must require user verification")
        for c in r.get("clients", []):
            cid = c.get("clientId")
            if claim_mapped(c, "tenant_id"):
                v.append(f"{cid}: citizen tokens must not carry tenant_id (the core refuses them)")
            if c.get("attributes", {}).get("civora.client-kind") == "relying-party":
                if "oidc-sha256-pairwise-sub-mapper" not in mappers(c):
                    v.append(f"{cid}: relying party needs a pairwise subject (P3-A3)")
                if c.get("publicClient"):
                    v.append(f"{cid}: relying party must be a confidential client")

    if profile == "staff":
        if r.get("registrationAllowed"):
            v.append("self-registration must be off")
        if int(r.get("ssoSessionMaxLifespan", 36000)) > 28800 or int(r.get("ssoSessionIdleTimeout", 1800)) > 1800:
            v.append("staff sessions: idle at most 30 min, absolute at most 8 h (Phase 0 §10.3)")
        for state in STATES["staff"]:
            if can_complete(r, r.get("browserFlow"), {"password", "otp", "passkey", "external-idp"}, state):
                v.append(f"browser flow can be completed without a FIDO2 security key for an account holding {'+'.join(sorted(state))} (P3-SEC5)")
        if not can_complete(r, r.get("browserFlow"), {"password", "security-key"}, {"password", "security-key"}):
            v.append("browser flow cannot be completed with password + security key")
        if r.get("webAuthnPolicyUserVerificationRequirement") != "required":
            v.append("security keys must require user verification (PIN or biometric)")
        if r.get("webAuthnPolicyAttestationConveyancePreference") not in ("direct", "enterprise"):
            v.append("security-key attestation must be verified (direct): otherwise any key, of any make, is accepted")
        if require_approved_keys and not r.get("webAuthnPolicyAcceptableAaguids"):
            v.append("no approved security-key models (AAGUID list) configured for this deployment")
        if not any(a.get("providerId") == "webauthn-register" and a.get("enabled") for a in r.get("requiredActions", [])):
            v.append("required action webauthn-register must be enabled")
        up = user_profile(r) or {}
        attr = next((a for a in up.get("attributes", []) if a.get("name") == "tenant_id"), None)
        if attr is None:
            v.append("user profile must declare tenant_id")
        else:
            perms = attr.get("permissions", {})
            if perms.get("edit") != ["admin"] or "user" in perms.get("view", []):
                v.append("tenant_id must be visible and editable by administrators only")
            if attr.get("validations", {}).get("pattern", {}).get("pattern") != UUID_PATTERN:
                v.append("tenant_id must be validated as a UUID")
        for c in r.get("clients", []):
            if c.get("attributes", {}).get("civora.client-kind") == "first-party" and not claim_mapped(c, "tenant_id"):
                v.append(f"{c.get('clientId')}: staff tokens need the tenant_id claim")
        v += idp_violations(r)
    return v


def idp_violations(r):
    """Institution SSO (P3-R1): every identity provider of the staff realm serves exactly one tenant."""
    v = []
    for idp in r.get("identityProviders", []):
        a = idp.get("alias")
        cfg = idp.get("config", {})
        if not (idp.get("hideOnLogin") or cfg.get("hideOnLoginPage") == "true"):
            v.append(f"identity provider {a}: must be hidden on the shared login page (it would list the institutions)")
        fb = first_broker_flow(r, idp)
        if links_accounts(r, fb):
            v.append(f"identity provider {a}: first-login flow {fb} can link to an existing account (takeover of a local or another tenant's account)")
        elif not contains_authenticator(r, fb, "idp-create-user-if-unique"):
            v.append(f"identity provider {a}: first-login flow {fb} must create the account only if unique")
        elif not contains_authenticator(r, fb, "idp-add-organization-member"):
            v.append(f"identity provider {a}: first-login flow {fb} must add the account to the tenant's organisation")
        if "organizationId" in idp and not idp.get("organizationId"):
            v.append(f"identity provider {a}: must be linked to its tenant's organisation")
        post = idp.get("postBrokerLoginFlowAlias")
        if not post or post not in flows_of(r):
            v.append(f"identity provider {a}: no post-login flow: the institution's sign-in alone would be enough (P3-SEC5)")
        elif can_complete(r, post, {"external-idp", "password", "otp", "passkey"}, {"security-key"}) or not can_complete(r, post, {"security-key"}, {"security-key"}):
            v.append(f"identity provider {a}: post-login flow {post} must require the account's security key (P3-SEC5)")
        mps = [m for m in r.get("identityProviderMappers", []) if m.get("identityProviderAlias") == a]
        tenant = [m for m in mps if m.get("identityProviderMapper") == "hardcoded-attribute-idp-mapper" and m.get("config", {}).get("attribute") == "tenant_id"]
        if len(tenant) != 1 or not re.match(UUID_PATTERN, tenant[0]["config"].get("attribute.value", "")) or tenant[0]["config"].get("syncMode") != "FORCE":
            v.append(f"identity provider {a}: needs exactly one hardcoded tenant_id mapper (a UUID, sync FORCE)")
        for m in mps:
            mc = m.get("config", {})
            if m.get("identityProviderMapper") != "hardcoded-attribute-idp-mapper" and "tenant_id" in (mc.get("user.attribute"), mc.get("attribute")):
                v.append(f"identity provider {a}: mapper {m.get('name')} lets the institution assert tenant_id")
        if idp.get("storeToken"):
            v.append(f"identity provider {a}: must not store the institution's tokens")
        if idp.get("providerId") in ("oidc", "keycloak-oidc"):
            if cfg.get("validateSignature") != "true":
                v.append(f"identity provider {a}: OIDC signatures must be validated")
            if cfg.get("pkceEnabled") != "true" or cfg.get("pkceMethod") != "S256":
                v.append(f"identity provider {a}: OIDC needs PKCE S256")
        elif idp.get("providerId") == "saml":
            if cfg.get("validateSignature") != "true" or cfg.get("wantAssertionsSigned") != "true":
                v.append(f"identity provider {a}: SAML responses and assertions must be signed and validated")
        else:
            v.append(f"identity provider {a}: protocol {idp.get('providerId')} not allowed (OIDC or SAML)")
    return v


def first(r, pred):
    return next(c for c in r["clients"] if pred(c))


def public_app(r):
    return first(r, lambda c: c.get("publicClient") and c.get("clientId") not in BUILT_IN_CLIENTS)


def flow(r, alias):
    return flows_of(r)[alias]


def mutations(profile, live=False, approved=False):
    m = {
        "refresh tokens not rotated": lambda r: r.update(revokeRefreshToken=False),
        "token lifetime 1 h": lambda r: r.update(accessTokenLifespan=3600),
        "weak password length": lambda r: r.update(passwordPolicy="length(8)"),
        "public client without PKCE": lambda r: public_app(r)["attributes"].pop("pkce.code.challenge.method"),
        "password grant enabled": lambda r: public_app(r).update(directAccessGrantsEnabled=True),
        "wildcard redirect": lambda r: public_app(r).update(redirectUris=["*"]),
        "password in file": lambda r: r.setdefault("users", [{}])[0].setdefault("credentials", []).append({"type": "password", "value": "x"}),
        "built-in direct-grant flow": lambda r: r.update(directGrantFlow="direct grant"),
        "offline tokens by default": _grant_offline_by_default,
    }
    if profile in ("citizens", "staff"):
        if profile == "citizens":
            web = lambda r: first(r, lambda c: c.get("clientId") == "civora-web")
            m["web app with a client secret"] = lambda r: web(r).update(clientAuthenticatorType="client-secret")
            m["web app as a public client"] = lambda r: web(r).update(publicClient=True)
            m["web app without PAR"] = lambda r: web(r)["attributes"].pop("require.pushed.authorization.requests")
            m["web app without DPoP"] = lambda r: web(r)["attributes"].update({"dpop.bound.access.tokens": "false"})
            mobile = lambda r: first(r, lambda c: c.get("clientId") == "civora-mobile")
            m["mobile app without PAR"] = lambda r: mobile(r)["attributes"].pop("require.pushed.authorization.requests")
            m["mobile app without DPoP"] = lambda r: mobile(r)["attributes"].pop("dpop.bound.access.tokens")
        m["sign-in events not stored"] = lambda r: r.update(eventsEnabled=False)
        m["sign-in events kept forever"] = lambda r: r.pop("eventsExpiration", None)
        m["failed sign-ins not recorded"] = lambda r: r.update(enabledEventTypes=["LOGIN"])
        m["no deny list of common passwords"] = lambda r: r.update(passwordPolicy=r["passwordPolicy"].replace(" and passwordBlacklist(civora-deny.txt)", ""))
        m["a context word allowed"] = lambda r: r.update(passwordPolicy=r["passwordPolicy"].replace("(?:civora|", "(?:"))
        m["unmanaged attributes enabled"] = lambda r: _set_up(r, unmanagedAttributePolicy="ENABLED")
        m["e-mail editable by the user"] = _attr_editable_by_user("email")
        m["username editable by the user"] = _attr_editable_by_user("username")
        m["phone number editable by the user"] = _attr_editable_by_user("phone_number")
        m["phone verification flag missing"] = _drop_attr("phone_number_verified")
        m["username edit allowed"] = lambda r: r.update(editUsernameAllowed=True)
        m["UPDATE_EMAIL action enabled"] = lambda r: r.setdefault("requiredActions", []).append(
            {"alias": "UPDATE_EMAIL", "name": "Update Email", "providerId": "UPDATE_EMAIL", "enabled": True, "defaultAction": False, "priority": 70, "config": {}})
        m["client without kind"] = lambda r: public_app(r)["attributes"].pop("civora.client-kind")
    if profile == "citizens":
        m["password without TOTP"] = lambda r: [e.update(requirement="DISABLED") for e in flow(r, "citizens-otp")["authenticationExecutions"]
                                               if e.get("authenticator") == "auth-otp-form"]
        m["TOTP enrolled at login (first-enrolment weakness)"] = lambda r: flow(r, "citizens-password").update(authenticationExecutions=[
            {"authenticator": "auth-username-password-form", "requirement": "REQUIRED", "priority": 10},
            {"authenticator": "auth-otp-form", "requirement": "REQUIRED", "priority": 20}])
        m["no refusal for accounts without a second factor"] = lambda r: flow(r, "citizens-password").update(authenticationExecutions=[
            e for e in flow(r, "citizens-password")["authenticationExecutions"] if e.get("flowAlias") != "citizens-no-second-factor"])
        m["username asked alone first (enumeration)"] = lambda r: flow(r, "citizens-password")["authenticationExecutions"].insert(
            0, {"authenticator": "auth-username-form", "requirement": "REQUIRED", "priority": 5})
        m["relying party without pairwise subject"] = lambda r: first(r, lambda c: c.get("attributes", {}).get("civora.client-kind") == "relying-party").update(protocolMappers=[])
        m["citizen token with tenant"] = lambda r: public_app(r)["protocolMappers"].append(
            {"name": "t", "protocolMapper": "oidc-usermodel-attribute-mapper", "config": {"claim.name": "tenant_id"}})
        m["Keycloak self-registration on (enumeration)"] = lambda r: r.update(registrationAllowed=True)
        m["e-mail verification off"] = lambda r: r.update(verifyEmail=False)
        m["provisioner with realm-admin"] = lambda r: next(u for u in r["users"] if u.get("serviceAccountClientId"))["clientRoles"][
            "realm-management"].append("realm-admin")
        m["provisioner allowed the browser flow"] = lambda r: first(r, lambda c: c.get("attributes", {}).get("civora.client-kind") == "service").update(
            standardFlowEnabled=True)
        m["passkey without user verification"] = lambda r: r.update(webAuthnPolicyPasswordlessUserVerificationRequirement="preferred")
    if live and profile == "citizens":
        m["pairwise salt missing"] = _drop_pairwise_salts
    if approved and profile == "staff":
        m["approved-key list emptied"] = lambda r: r.update(webAuthnPolicyAcceptableAaguids=[])
    if profile == "staff":
        m["security-key step disabled"] = lambda r: [e.update(requirement="DISABLED") for e in flow(r, "staff-key")["authenticationExecutions"]
                                                    if e.get("authenticator") == "webauthn-authenticator"]
        m["OTP instead of security key"] = lambda r: [e.update(authenticator="auth-otp-form") for e in flow(r, "staff-key")["authenticationExecutions"]
                                                     if e.get("authenticator") == "webauthn-authenticator"]
        m["key enrolled at login (first-enrolment weakness)"] = lambda r: flow(r, "staff-forms").update(authenticationExecutions=[
            {"authenticator": "auth-username-password-form", "requirement": "REQUIRED", "priority": 10},
            {"authenticator": "webauthn-authenticator", "requirement": "REQUIRED", "priority": 20}])
        m["no refusal for accounts without a key"] = lambda r: flow(r, "staff-forms").update(authenticationExecutions=[
            e for e in flow(r, "staff-forms")["authenticationExecutions"] if e.get("flowAlias") != "staff-no-second-factor"])
        m["built-in browser flow"] = lambda r: r.update(browserFlow="browser", authenticationFlows=r["authenticationFlows"] + [
            {"alias": "browser", "authenticationExecutions": [{"authenticator": "auth-cookie", "requirement": "ALTERNATIVE"},
                                                              {"authenticator": "auth-username-password-form", "requirement": "ALTERNATIVE"}]}])
        m["tenant editable by the user"] = _tenant_editable_by_user
        m["self-registration"] = lambda r: r.update(registrationAllowed=True)
        m["attestation not verified (any key accepted)"] = lambda r: r.update(webAuthnPolicyAttestationConveyancePreference="none")
        m["staff token without tenant"] = lambda r: public_app(r).update(protocolMappers=[x for x in public_app(r)["protocolMappers"]
                                                                                          if x.get("config", {}).get("claim.name") != "tenant_id"])
        m["staff session of 10 h"] = lambda r: r.update(ssoSessionMaxLifespan=36000)
        m["SSO: provider links to existing accounts"] = lambda r: _weak_idp(r, firstBrokerLoginFlowAlias="first broker login")
        m["SSO: institution sign-in without the security key"] = lambda r: _weak_idp(r, postBrokerLoginFlowAlias=None)
        m["SSO: provider listed on the login page"] = lambda r: _weak_idp(r, hideOnLogin=False)
        m["SSO: institution asserts tenant_id"] = lambda r: _weak_idp(r, extra_mapper={"name": "t", "identityProviderMapper": "oidc-user-attribute-idp-mapper",
                                                                                          "config": {"claim": "tenant", "user.attribute": "tenant_id"}})
        m["SSO: no tenant mapper"] = lambda r: _weak_idp(r, tenant=False)
        m["SSO: OIDC signatures not validated"] = lambda r: _weak_idp(r, cfg={"validateSignature": "false"})
        m["SSO: SAML assertions unsigned"] = lambda r: _weak_idp(r, providerId="saml", cfg={"validateSignature": "true", "wantAssertionsSigned": "false"})
    return m


def _weak_idp(r, extra_mapper=None, tenant=True, cfg=None, **kw):
    """Adds an institution identity provider that follows every rule except the one weakened by the arguments."""
    idp = {"alias": "weak-idp", "providerId": "oidc", "enabled": True, "hideOnLogin": True, "storeToken": False,
           "firstBrokerLoginFlowAlias": "staff-first-broker-login", "postBrokerLoginFlowAlias": "staff-post-broker-key",
           "config": {"validateSignature": "true", "pkceEnabled": "true", "pkceMethod": "S256"}}
    idp.update(kw)
    idp["config"].update(cfg or {})
    if idp.get("postBrokerLoginFlowAlias") is None:
        idp.pop("postBrokerLoginFlowAlias")
    r.setdefault("identityProviders", []).append(idp)
    mps = r.setdefault("identityProviderMappers", [])
    if tenant:
        mps.append({"name": "tenant", "identityProviderAlias": "weak-idp", "identityProviderMapper": "hardcoded-attribute-idp-mapper",
                    "config": {"attribute": "tenant_id", "attribute.value": "6f1c2a3b-4d5e-4f60-8a7b-9c0d1e2f3a4b", "syncMode": "FORCE"}})
    if extra_mapper:
        mps.append({**extra_mapper, "identityProviderAlias": "weak-idp"})


def _drop_pairwise_salts(r):
    for c in r["clients"]:
        for mp in c.get("protocolMappers", []):
            if mp.get("protocolMapper") == "oidc-sha256-pairwise-sub-mapper":
                mp.setdefault("config", {}).pop("pairwiseSubAlgorithmSalt", None)


def _grant_offline_by_default(r):
    name = (r.get("defaultRole") or {}).get("name", f"default-roles-{r.get('realm')}")
    roles = r.setdefault("roles", {}).setdefault("realm", [])
    role = next((x for x in roles if x.get("name") == name), None)
    if role is None:
        role = {"name": name, "composite": True}
        roles.append(role)
    role.setdefault("composites", {}).setdefault("realm", []).append("offline_access")


def _edit_up(r, fn):
    """Applies fn to the parsed user-profile configuration of a realm and stores it back."""
    comp = r["components"]["org.keycloak.userprofile.UserProfileProvider"][0]["config"]
    up = json.loads(comp["kc.user.profile.config"][0])
    fn(up)
    comp["kc.user.profile.config"] = [json.dumps(up)]


def _set_up(r, **kw):
    _edit_up(r, lambda up: up.update(kw))


def _attr_editable_by_user(name):
    def f(r):
        _edit_up(r, lambda up: next(a for a in up["attributes"] if a["name"] == name)["permissions"].update(edit=["admin", "user"]))
    return f


def _drop_attr(name):
    def f(r):
        _edit_up(r, lambda up: up.update(attributes=[a for a in up["attributes"] if a["name"] != name]))
    return f


def _tenant_editable_by_user(r):
    _edit_up(r, lambda up: next(a for a in up["attributes"] if a["name"] == "tenant_id")["permissions"].update(edit=["admin", "user"]))


def main():
    args = sys.argv[1:]
    profile = "dev"
    if "--profile" in args:
        profile = args[args.index("--profile") + 1]
        if profile not in ALLOWED_DEFAULT_ROLES:
            sys.exit(f"unknown profile {profile}")
    realm = json.load(open(args[0]))
    live = "--live" in args
    approved = "--require-approved-keys" in args
    found = violations(realm, profile, live, approved)
    for x in found:
        print(f"  FAIL {x}")
    if not found:
        print(f"  ok   realm {realm.get('realm')} ({profile} profile): {len(realm.get('clients', []))} clients, flows and roles conform")
    if "--self-test" in args:
        for name, mutate in mutations(profile, live, approved).items():
            weak = copy.deepcopy(realm)
            mutate(weak)
            if violations(weak, profile, live, approved):
                print(f"  ok   negative control rejected: {name}")
            else:
                print(f"  FAIL negative control NOT rejected: {name}")
                found.append(name)
    sys.exit(1 if found else 0)


if __name__ == "__main__":
    main()
